-- Mapping-level SQL Query override (from Source Qualifier 'Sql Query' property)
SELECT
   BOOKINGS_MEASURE_KEY,
   BKGS_MEASURE_TRANS_TYPE_CODE,
   BOOKINGS_PROCESS_DATE,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER,
   RU_SERVICE_CONTRACT_START_DTM,
   RU_SERVICE_CONTRACT_END_DTM,
   /*SVAKULAB*/
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
         THEN CASE
            WHEN CASE
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
                  THEN CASE
                     WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                        THEN 0
                     ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
                  END
               WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
                  THEN 0
               ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
            END <> 0
            AND DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) <> 0
               THEN (((((TRUNC(COALESCE(MT.DV_CONTRACT_DURATION, 12) / 12)) * 365 - NXSSIST.FULFILLMENT_TERM_DAYS_CNT) - (DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) / CASE
                  WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
                  AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
                     THEN CASE
                        WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                           THEN 0
                        ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
                     END
                  WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
                     THEN 0
                  ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
               END)) * 12) / 365)
            ELSE 0
         END
      ELSE CASE
         WHEN CASE
            WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
            AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
               THEN CASE
                  WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                     THEN 0
                  ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
               END
            WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
               THEN 0
            ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
         END <> 0
         AND DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) <> 0
            THEN (((((TRUNC(COALESCE(MT.DV_CONTRACT_DURATION, 12) / 12)) * 365 - CASE
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('REPLACE', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD = 'ADD'*/
                  THEN 0
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD IN ('ADD','REMOVE')*/
                  THEN 0
               ELSE NXSSIST.FULFILLMENT_TERM_DAYS_CNT
            END) - (DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) / CASE
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
                  THEN CASE
                     WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                        THEN 0
                     ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
                  END
               WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
                  THEN 0
               ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
            END)) * 12) / 365)
         ELSE 0
      END
   END AS DV_CONTRACT_DURATION,
   DV_ANNUALIZED_FLG,
   DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) AS DV_ANNUALIZED_US_NET_AMT,
   DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) AS DV_MULTIYEAR_US_NET_AMT,
   /*SVAKULAB*/
   CASE
      WHEN CONTRACT_DURATION <> 0
         THEN (MY_AMT) / CONTRACT_DURATION
      ELSE 0
   END AS PER_MONTH_AMT,
   ((CAST(TRUNC((CONTRACT_DURATION) / 12.00) AS INTEGER))) + 1 CONTRACT_TERM,
   RSTART.FISCAL_YEAR_MONTH_INT CONTRACT_START_MONTH,
   RSTART.FISCAL_YEAR_WEEK_NUM_INT CONTRACT_START_WEEK,
   RBKGS.FISCAL_YEAR_MONTH_INT BOOKINGS_PROCESS_MONTH,
   RBKGS.FISCAL_YEAR_WEEK_NUM_INT BOOKINGS_PROCESS_WEEK,
   CASE
      WHEN RSTART.FISCAL_YEAR_MONTH_INT IS NOT NULL
         THEN 'Software'
      WHEN CONTRACT_DURATION IS NOT NULL
      AND (MT.RU_SERVICE_CONTRACT_START_DTM IS NULL
      OR MT.RU_SERVICE_CONTRACT_END_DTM IS NULL)
         THEN 'Software'
      WHEN CONTRACT_DURATION IS NOT NULL
      AND (CAST(MT.RU_SERVICE_CONTRACT_END_DTM AS DATE) - CAST(MT.RU_SERVICE_CONTRACT_START_DTM AS DATE)) = 0
         THEN 'Software'
      ELSE 'UNKNOWN'
   END AS ANNUITY_TYPE,
   MT.DV_MTHLY_RCR_REV_TRXL_USD_AMT MRR,
   MT.DV_INCRML_MTHY_RCRR_RV_USD_AMT IMRR,
   MT.DD_COMP_US_NET_PRICE_AMOUNT /* * COALESCE(SWFTR.ALLOCATION_PCT,1) */ BOOK_NET,
   (TRUNC(COALESCE(MT.DV_CONTRACT_DURATION, 12) / 12)) * 365 ORIG_SUB_DAYS,
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('REPLACE', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD = 'ADD'*/
         THEN 0
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD IN ('ADD','REMOVE')*/
         THEN 0
      ELSE NXSSIST.FULFILLMENT_TERM_DAYS_CNT
   END AS FULFILLMENT_TERM_DAYS_CNT,
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('REPLACE', 'en-ci-rtrim'), COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'), COLLATE('NOCHANGE', 'en-ci-rtrim'), COLLATE('DOWNSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD = 'ADD'*/
         THEN MRR
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('NEW', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('NOCHANGE', 'en-ci-rtrim'))
      AND COLLATE(NXSSIST.ACTION_CD, 'en-ci-rtrim') = 'ADD'
         THEN MRR
      WHEN COLLATE(NXSSIST.BK_SALES_ORDER_TYPE_CD, 'en-ci-rtrim') = 'AUTO-RENEWAL'
         THEN MRR
      ELSE IMRR
   END MONTHLY_RATE,
   MONTHLY_RATE * 12 / 365 DAILY_RATE_FROM_MONTHLY,
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
         THEN CASE
            WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
               THEN 0
            ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
         END
      WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
         THEN 0
      ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
   END AS DAILY_RATE,
   (365 - (MOD(FULFILLMENT_TERM_DAYS, 365))) AS BKGS_START_YEAR_DAYS,
   BKGSSTART.CALENDAR_DATE AS BKGS_START_DATE,
   BKGSSTART.FISCAL_YEAR_MONTH_INT AS BKGS_START_MONTH,
   BKGSSTART.FISCAL_YEAR_NUMBER_INT AS BKGS_START_YEAR,
   BKGSEND.CALENDAR_DATE - BKGSEND.FISCAL_YEAR_START_DATE AS BKGS_END_YEAR_DAYS,
   BKGSEND.CALENDAR_DATE AS BKGS_END_DATE,
   BKGSEND.FISCAL_YEAR_MONTH_INT AS BKGS_END_MONTH,
   BKGSEND.FISCAL_YEAR_WEEK_NUM_INT AS BKGS_END_WEEK,
   BKGSEND.FISCAL_YEAR_NUMBER_INT AS BKGS_END_YEAR,
   MT.DV_FMV_FLG,
   MT.ADJUSTMENT_CODE,
   MT.ACQUISITION_ORDER_ORIGIN_CD,
   MT.ACQUISITION_ROLE
FROM
   {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE MT
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_SLSORDVWDB') }}.N_XAAS_SO_SBSCR_ITM_SLS_TRX NXSSIST
      ON MT.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY = NXSSIST.SO_SBSCRPTN_ITM_SLS_TRX_KEY
   INNER JOIN
      (
         SELECT
            DV_FISCAL_YEAR_QUARTER_NUM_INT,
            PRODUCT_KEY,
            BK_PRDT_ALLCTN_METRIC_CD,
            BK_PRDT_ALLCTN_CLSFCTN_CD,
            ALLOCATION_PCT
         FROM
            {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.N_PRDT_TO_PRDT_CLSFTN_ALCTN
         WHERE
            RTRIM(BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
         GROUP BY
            1,
            2,
            3,
            4,
            5
      ) ALCTN
      ON MT.PRODUCT_KEY = ALCTN.PRODUCT_KEY
      AND MT.FISCAL_YEAR_QUARTER_NUMBER_INT = ALCTN.DV_FISCAL_YEAR_QUARTER_NUM_INT
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RSTART
      ON (MT.BOOKINGS_PROCESS_DATE - FULFILLMENT_TERM_DAYS) = RSTART.CALENDAR_DATE
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR BKGSSTART
      ON (CAST(MT.BOOKINGS_PROCESS_DATE AS DATE)) = BKGSSTART.CALENDAR_DATE
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR BKGSEND
      ON BKGSEND.CALENDAR_DATE = CASE
         WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
         AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
            THEN (CAST(MT.BOOKINGS_PROCESS_DATE AS DATE) + (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT))
         ELSE (CAST(MT.BOOKINGS_PROCESS_DATE AS DATE) + (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS))
      END
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RBKGS
      ON MT.BOOKINGS_PROCESS_DATE = RBKGS.CALENDAR_DATE
WHERE
   COLLATE(SERVICE_FLG, 'en-ci-rtrim') = 'N'
   AND COLLATE(DV_ANNUALIZED_FLG, 'en-ci-rtrim') = 'N'
   AND RTRIM(ALCTN.BK_PRDT_ALLCTN_CLSFCTN_CD) IN (COLLATE('Software', 'en-ci-rtrim'))
   AND RTRIM(MT.BKGS_MEASURE_TRANS_TYPE_CODE) IN (COLLATE('XAAS', 'en-ci-rtrim'))
   AND MT.DV_FISCAL_YEAR_MTH_NUMBER_INT IN (
      SELECT
         FISCAL_YEAR_MTH_NUMBER_INT
      FROM
         {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_ETLVWDB') }}.BKG_PROCESS_DT_CNTRL
   )
UNION
SELECT
   BOOKINGS_MEASURE_KEY,
   BKGS_MEASURE_TRANS_TYPE_CODE,
   BOOKINGS_PROCESS_DATE,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER,
   RU_SERVICE_CONTRACT_START_DTM,
   RU_SERVICE_CONTRACT_END_DTM,
   /*SVAKULAB*/
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
         THEN CASE
            WHEN CASE
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
                  THEN CASE
                     WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                        THEN 0
                     ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
                  END
               WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
                  THEN 0
               ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
            END <> 0
            AND DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) <> 0
               THEN (((((TRUNC(COALESCE(MT.DV_CONTRACT_DURATION, 12) / 12)) * 365 - NXSSIST.FULFILLMENT_TERM_DAYS_CNT) - (DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) / CASE
                  WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
                  AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
                     THEN CASE
                        WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                           THEN 0
                        ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
                     END
                  WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
                     THEN 0
                  ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
               END)) * 12) / 365)
            ELSE 0
         END
      ELSE CASE
         WHEN CASE
            WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
            AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
               THEN CASE
                  WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                     THEN 0
                  ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
               END
            WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
               THEN 0
            ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
         END <> 0
         AND DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) <> 0
            THEN (((((TRUNC(COALESCE(MT.DV_CONTRACT_DURATION, 12) / 12)) * 365 - CASE
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('REPLACE', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD = 'ADD'*/
                  THEN 0
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD IN ('ADD','REMOVE')*/
                  THEN 0
               ELSE NXSSIST.FULFILLMENT_TERM_DAYS_CNT
            END) - (DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) / CASE
               WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
               AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
                  THEN CASE
                     WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
                        THEN 0
                     ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
                  END
               WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
                  THEN 0
               ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
            END)) * 12) / 365)
         ELSE 0
      END
   END AS DV_CONTRACT_DURATION,
   DV_ANNUALIZED_FLG,
   DV_ANNUALIZED_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) AS DV_ANNUALIZED_US_NET_AMT,
   DV_MULTIYEAR_US_NET_AMT * COALESCE(ALCTN.ALLOCATION_PCT, 1) AS DV_MULTIYEAR_US_NET_AMT,
   /*SVAKULAB*/
   CASE
      WHEN CONTRACT_DURATION <> 0
         THEN (MY_AMT) / CONTRACT_DURATION
      ELSE 0
   END AS PER_MONTH_AMT,
   ((CAST(TRUNC((CONTRACT_DURATION) / 12.00) AS INTEGER))) + 1 CONTRACT_TERM,
   RSTART.FISCAL_YEAR_MONTH_INT CONTRACT_START_MONTH,
   RSTART.FISCAL_YEAR_WEEK_NUM_INT CONTRACT_START_WEEK,
   RBKGS.FISCAL_YEAR_MONTH_INT BOOKINGS_PROCESS_MONTH,
   RBKGS.FISCAL_YEAR_WEEK_NUM_INT BOOKINGS_PROCESS_WEEK,
   CASE
      WHEN RSTART.FISCAL_YEAR_MONTH_INT IS NOT NULL
         THEN 'Software'
      WHEN CONTRACT_DURATION IS NOT NULL
      AND (MT.RU_SERVICE_CONTRACT_START_DTM IS NULL
      OR MT.RU_SERVICE_CONTRACT_END_DTM IS NULL)
         THEN 'Software'
      WHEN CONTRACT_DURATION IS NOT NULL
      AND (CAST(MT.RU_SERVICE_CONTRACT_END_DTM AS DATE) - CAST(MT.RU_SERVICE_CONTRACT_START_DTM AS DATE)) = 0
         THEN 'Software'
      ELSE 'UNKNOWN'
   END AS ANNUITY_TYPE,
   MT.DV_MTHLY_RCR_REV_TRXL_USD_AMT MRR,
   MT.DV_INCRML_MTHY_RCRR_RV_USD_AMT IMRR,
   MT.DD_COMP_US_NET_PRICE_AMOUNT /* * COALESCE(SWFTR.ALLOCATION_PCT,1) */ BOOK_NET,
   (TRUNC(COALESCE(MT.DV_CONTRACT_DURATION, 12) / 12)) * 365 ORIG_SUB_DAYS,
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('REPLACE', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD = 'ADD'*/
         THEN 0
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD IN ('ADD','REMOVE')*/
         THEN 0
      ELSE NXSSIST.FULFILLMENT_TERM_DAYS_CNT
   END AS FULFILLMENT_TERM_DAYS_CNT,
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('REPLACE', 'en-ci-rtrim'), COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'), COLLATE('NOCHANGE', 'en-ci-rtrim'), COLLATE('DOWNSELL', 'en-ci-rtrim')) /*AND NXSSIST.ACTION_CD = 'ADD'*/
         THEN MRR
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('NEW', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('NOCHANGE', 'en-ci-rtrim'))
      AND COLLATE(NXSSIST.ACTION_CD, 'en-ci-rtrim') = 'ADD'
         THEN MRR
      WHEN COLLATE(NXSSIST.BK_SALES_ORDER_TYPE_CD, 'en-ci-rtrim') = 'AUTO-RENEWAL'
         THEN MRR
      ELSE IMRR
   END MONTHLY_RATE,
   MONTHLY_RATE * 12 / 365 DAILY_RATE_FROM_MONTHLY,
   CASE
      WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
      AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
         THEN CASE
            WHEN ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT <= 0
               THEN 0
            ELSE BOOK_NET / (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT)
         END
      WHEN ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS <= 0
         THEN 0
      ELSE BOOK_NET / (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS)
   END AS DAILY_RATE,
   (365 - (MOD(FULFILLMENT_TERM_DAYS, 365))) AS BKGS_START_YEAR_DAYS,
   BKGSSTART.CALENDAR_DATE AS BKGS_START_DATE,
   BKGSSTART.FISCAL_YEAR_MONTH_INT AS BKGS_START_MONTH,
   BKGSSTART.FISCAL_YEAR_NUMBER_INT AS BKGS_START_YEAR,
   BKGSEND.CALENDAR_DATE - BKGSEND.FISCAL_YEAR_START_DATE AS BKGS_END_YEAR_DAYS,
   BKGSEND.CALENDAR_DATE AS BKGS_END_DATE,
   BKGSEND.FISCAL_YEAR_MONTH_INT AS BKGS_END_MONTH,
   BKGSEND.FISCAL_YEAR_WEEK_NUM_INT AS BKGS_END_WEEK,
   BKGSEND.FISCAL_YEAR_NUMBER_INT AS BKGS_END_YEAR,
   MT.DV_FMV_FLG,
   MT.ADJUSTMENT_CODE,
   MT.ACQUISITION_ORDER_ORIGIN_CD,
   MT.ACQUISITION_ROLE
FROM
   {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE MT
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_SLSORDVWDB') }}.N_XAAS_SO_SBSCR_ITM_SLS_TRX NXSSIST
      ON MT.DV_SO_SBSCRPTN_ITM_SLS_TRX_KEY = NXSSIST.SO_SBSCRPTN_ITM_SLS_TRX_KEY
   INNER JOIN
      (
         SELECT
            DV_FISCAL_YEAR_QUARTER_NUM_INT,
            PRODUCT_KEY,
            BK_PRDT_ALLCTN_METRIC_CD,
            BK_PRDT_ALLCTN_CLSFCTN_CD,
            ALLOCATION_PCT
         FROM
            {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.N_PRDT_TO_PRDT_CLSFTN_ALCTN
         WHERE
            RTRIM(BK_PRDT_ALLCTN_METRIC_CD) IN (COLLATE('BOOKINGS', 'en-ci-rtrim'), COLLATE('UNKNOWN', 'en-ci-rtrim'))
         GROUP BY
            1,
            2,
            3,
            4,
            5
      ) ALCTN
      ON MT.PRODUCT_KEY = ALCTN.PRODUCT_KEY
      AND MT.FISCAL_YEAR_QUARTER_NUMBER_INT = ALCTN.DV_FISCAL_YEAR_QUARTER_NUM_INT
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RSTART
      ON (MT.BOOKINGS_PROCESS_DATE - FULFILLMENT_TERM_DAYS) = RSTART.CALENDAR_DATE
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR BKGSSTART
      ON (CAST(MT.BOOKINGS_PROCESS_DATE AS DATE)) = BKGSSTART.CALENDAR_DATE
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR BKGSEND
      ON BKGSEND.CALENDAR_DATE = CASE
         WHEN RTRIM(NXSSIST.BK_SALES_ORDER_TYPE_CD) IN (COLLATE('MODIFY', 'en-ci-rtrim'))
         AND RTRIM(NXSSIST.BK_SALES_ORDER_SELL_TYPE_CD) IN (COLLATE('UPSELL', 'en-ci-rtrim'))
            THEN (CAST(MT.BOOKINGS_PROCESS_DATE AS DATE) + (ORIG_SUB_DAYS - NXSSIST.FULFILLMENT_TERM_DAYS_CNT))
         ELSE (CAST(MT.BOOKINGS_PROCESS_DATE AS DATE) + (ORIG_SUB_DAYS - FULFILLMENT_TERM_DAYS))
      END
   INNER JOIN
      {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR RBKGS
      ON MT.BOOKINGS_PROCESS_DATE = RBKGS.CALENDAR_DATE
WHERE
   COLLATE(SERVICE_FLG, 'en-ci-rtrim') = 'Y'
   AND COLLATE(DV_ANNUALIZED_FLG, 'en-ci-rtrim') = 'N'
   --AND ALCTN.BK_PRDT_ALLCTN_CLSFCTN_CD  IN  ( 'Software'  )
   AND RTRIM(MT.BKGS_MEASURE_TRANS_TYPE_CODE) IN (COLLATE('XAAS', 'en-ci-rtrim'))
   AND MT.DV_FISCAL_YEAR_MTH_NUMBER_INT IN (
      SELECT
         FISCAL_YEAR_MTH_NUMBER_INT
      FROM
         {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_ETLVWDB') }}.BKG_PROCESS_DT_CNTRL
   )
{% endif %}